import java.util.IdentityHashMap;
import java.util.Map;

public class PersistenceContextSimulation {
    public void demonstrateIdentity() {
        String key1 = new String("entity_id_1");
        String key2 = new String("entity_id_1");

        Map<String, String> identityMap = new IdentityHashMap<>();
        identityMap.put(key1, "ManagedEntityA");

        // Returns null because key2 is a different object instance in heap
        System.out.println(identityMap.get(key2)); 

        // Returns "ManagedEntityA" because we use the exact same reference
        System.out.println(identityMap.get(key1));
    }
}
